use std :: fmt :: Display ; use regex :: Regex ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use pretty_assertions :: assert_eq ; use super :: * ; impl ToolName { pub fn into_string (self) -> String { self . 0 } pub fn as_str (& self) -> & str { & self . 0 } pub fn into_sanitized (self) -> Self { ToolName :: sanitized (self . 0 . as_str ()) } # [doc = " Converts a Claude Code format MCP tool name (`mcp__{server}__{tool}`) to"] # [doc = " Forge's internal legacy format (`mcp_{server}_tool_{tool}`)."] # [doc = ""] # [doc = " Returns `None` if the name does not match the Claude Code MCP format."] # [doc = " Sanitized names never contain `__`, so the first `__` is always the"] # [doc = " server/tool separator."] pub fn to_legacy_mcp_name (& self) -> Option < ToolName > { let rest = self . 0 . strip_prefix ("mcp__") ? ; let (server , tool) = rest . split_once ("__") ? ; Some (ToolName :: new (format ! ("mcp_{server}_tool_{tool}"))) } }